        IF "DB1_SYS".Pulso1seg THEN
            "DB1_SYS".Aux.Contador1h += 1;
            IF "DB1_SYS".Aux.Contador1h &gt;= 3600 THEN
                "DB1_SYS".Pulso1h := TRUE;
                "DB1_SYS".Aux.Contador1h := 0;
            END_IF;
        END_IF;

