            "DB1_SYS".FlipFlop2seg := TRUE;
        ELSIF "DB1_SYS".Pulso2seg AND "DB1_SYS".FlipFlop2seg THEN
            "DB1_SYS".FlipFlop2seg := FALSE;
        END_IF;

        //  Flip Flop 5 segundos
