                        IF "DB2015_M".Mux[#for_mux].M.Config_HabilitarRetornoConfMarcha &lt;&gt; "DB2015_M".M[#t_Index].Config_HabilitarRetornoConfMarcha THEN
                            "DB2015_M".M[#t_Index].Config_HabilitarRetornoConfMarcha := "DB2015_M".Mux[#for_mux].M.Config_HabilitarRetornoConfMarcha;
